import numpy as np
import xarray as xr
from geocat.comp import gradient

def test_numpy_array():
    print("Testing numpy array...")
    data = np.random.rand(10, 20)
    lat = np.linspace(-90, 90, 10)
    lon = np.linspace(-180, 180, 20)
    try:
        # This should work if we pass lat and lon as kwargs
        res = gradient(data, lat=lat, lon=lon)
        print("Numpy array success!")
    except Exception as e:
        print(f"Numpy array failed: {e}")
        raise e

def test_xarray_2d_coords():
    print("Testing xarray with 2D coords...")
    lat = np.linspace(-90, 90, 10)
    lon = np.linspace(-180, 180, 20)
    lon2d, lat2d = np.meshgrid(lon, lat)
    data = xr.DataArray(
        np.random.rand(10, 20),
        coords={'lat': (['lat', 'lon'], lat2d), 'lon': (['lat', 'lon'], lon2d)},
        dims=['lat', 'lon']
    )
    try:
        res = gradient(data)
        print("Xarray 2D coords success!")
    except Exception as e:
        print(f"Xarray 2D coords failed: {e}")
        raise e

if __name__ == "__main__":
    try:
        test_numpy_array()
    except Exception:
        pass
    try:
        test_xarray_2d_coords()
    except Exception:
        pass
